//! Files this project did not write.
//!
//! Every other fidelity test in the repository asserts against a document whose
//! shape we chose — written by our own exporter, or generated by our own script.
//! That is circular in the way that matters: it proves the importer agrees with
//! the exporter, and says nothing about whether either agrees with Excel.
//!
//! These are real files produced by Microsoft Excel, taken from Apache POI's
//! test data (Apache-2.0, provenance recorded in `fixtures/manifest.json`). They
//! contain the things a real document contains and a hand-written fixture does
//! not: a chart, a classic header, conditional formatting, defined names,
//! several hundred rows of somebody's actual data, and parts this project has
//! never emitted.
//!
//! What is asserted is deliberately modest, and it is the assertion that was
//! missing rather than a better one. An importer that opens a real file and
//! produces a sheet with cells in it has cleared the bar these files exist to
//! set; whether every colour matches is the oracle's job. Silently returning an
//! empty workbook is **not** clearing it, which is why the cell count is checked
//! — that is the shape a "successful" import takes when it has quietly skipped
//! everything it did not recognise.

use std::path::PathBuf;

fn corpus() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/corpus")
}

/// Every corpus file, or nothing if the corpus is absent.
fn files() -> Vec<PathBuf> {
    let Ok(entries) = std::fs::read_dir(corpus()) else {
        return Vec::new();
    };
    let mut found: Vec<PathBuf> = entries
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "xlsx"))
        .collect();
    // Sorted, so a failure names the same file on every machine.
    found.sort();
    found
}

#[test]
fn the_corpus_is_present() {
    // A guard against every test below passing because there is nothing to run
    // them on. A corpus that quietly disappears takes its coverage with it and
    // leaves the suite green.
    assert!(
        files().len() >= 5,
        "expected the real-producer corpus in fixtures/corpus; found {:?}",
        files()
    );
}

#[test]
fn every_real_file_opens() {
    let mut total_cells = 0usize;
    let mut opened = 0usize;
    let mut refused: Vec<String> = Vec::new();
    for path in files() {
        let bytes = std::fs::read(&path).expect("the file is readable");
        let name = path.file_name().unwrap().to_string_lossy().into_owned();

        // Opened, or refused with a reason. Both are correct answers and the
        // corpus contains both: `49609.xlsx` is a package with no
        // `_rels/.rels`, which is not a spreadsheet however much it is named
        // like one, and refusing it is the right behaviour rather than a gap.
        //
        // What neither may be is a panic or a hang, and that is the assertion —
        // these are files this project did not write, arriving from anywhere,
        // and "we crash on this one" is not a thing a user can work around.
        match casual_calc_import::import_package(bytes) {
            Ok(import) => {
                assert!(
                    !import.workbook.sheets.is_empty(),
                    "{name} opened with no sheets at all"
                );
                opened += 1;
                total_cells += import
                    .workbook
                    .sheets
                    .iter()
                    .map(|sheet| sheet.cells.iter().count())
                    .sum::<usize>();
            }
            Err(why) => {
                refused.push(format!("{name}: {why}"));
            }
        }
    }

    // Corpus-wide rather than per file, and the reason is a finding rather than
    // a convenience. The first version asserted every file yields cells, and
    // `47668.xlsx` failed it — correctly: that file is a workbook containing
    // only an image, its `<sheetData/>` is genuinely empty, and the importer was
    // right. A real corpus contains files like that, which is exactly why it is
    // worth having and why an assumption written against documents we wrote does
    // not survive contact with it.
    //
    // What the count still catches is the failure worth catching: an importer
    // that recognises nothing, reports success and returns an empty workbook
    // looks precisely like one that worked, until somebody notices their data is
    // gone. That cannot hide behind a total this size.
    assert!(
        total_cells > 100,
        "the whole corpus yielded only {total_cells} cells, which is what silently \
         importing nothing looks like"
    );
    // A guard against the refusals quietly becoming the rule. If most of a
    // corpus of real files stops opening, this suite should say so rather than
    // pass because every failure was a *clean* failure.
    assert!(
        opened * 2 > files().len(),
        "only {opened} of {} opened; refusals: {refused:#?}",
        files().len()
    );
}

#[test]
fn opening_a_real_file_twice_gives_the_same_workbook() {
    // Determinism against input nobody here designed. The engine's determinism
    // is asserted all over the place against documents we wrote; this asks the
    // same question of files whose parts arrive in an order we did not choose,
    // which is where an incidental dependence on iteration order would show.
    for path in files() {
        let bytes = std::fs::read(&path).expect("the file is readable");
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let (Ok(once), Ok(twice)) = (
            casual_calc_import::import_package(bytes.clone()),
            casual_calc_import::import_package(bytes),
        ) else {
            // Refused, and refused both times — determinism is only a question
            // for the files that open. A package with no `_rels/.rels` is not a
            // spreadsheet however it is named, and saying so twice is
            // consistent behaviour rather than a gap.
            continue;
        };
        assert_eq!(
            once.workbook.to_snapshot().unwrap(),
            twice.workbook.to_snapshot().unwrap(),
            "{name} imported differently the second time"
        );
    }
}

/// Strict Open XML, which Excel can save and which uses different namespaces.
///
/// Recorded as a defect on the strength of a grep — 22 matches for the
/// transitional namespace, none for the strict one — and the grep was right
/// about the counts and wrong about the conclusion. The readers match element
/// **local names** rather than namespace URIs, in forty-nine places, so a strict
/// file parses without anything special. It was designed that way; nobody had
/// checked it since.
///
/// The test exists so it stays true. A reader tightened later to match on a
/// namespace would be a reasonable-looking change that silently stops opening
/// files Excel produces, and nothing else here would notice.
#[test]
fn a_strict_open_xml_workbook_reads_the_same_as_a_transitional_one() {
    const TRANSITIONAL_MAIN: &str = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
    const STRICT_MAIN: &str = "http://purl.oclc.org/ooxml/spreadsheetml/main";
    const TRANSITIONAL_REL: &str =
        "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
    const STRICT_REL: &str = "http://purl.oclc.org/ooxml/officeDocument/relationships";

    for path in files() {
        let bytes = std::fs::read(&path).expect("readable");
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let Ok(transitional) = casual_calc_import::import_package(bytes.clone()) else {
            continue; // refused either way; nothing to compare
        };

        // Rewrite every part's namespaces, which is the difference between the
        // two flavours as far as a reader is concerned.
        let mut strict = Vec::new();
        {
            let reader = std::io::Cursor::new(&bytes);
            let mut zin = zip::ZipArchive::new(reader).expect("a package");
            let mut zout = zip::ZipWriter::new(std::io::Cursor::new(&mut strict));
            for i in 0..zin.len() {
                let mut entry = zin.by_index(i).expect("entry");
                let entry_name = entry.name().to_owned();
                let mut data = Vec::new();
                std::io::Read::read_to_end(&mut entry, &mut data).expect("read");
                if entry_name.ends_with(".xml")
                    && let Ok(text) = String::from_utf8(data.clone())
                {
                    data = text
                        .replace(TRANSITIONAL_MAIN, STRICT_MAIN)
                        .replace(TRANSITIONAL_REL, STRICT_REL)
                        .into_bytes();
                }
                zout.start_file(entry_name, zip::write::SimpleFileOptions::default())
                    .expect("start");
                std::io::Write::write_all(&mut zout, &data).expect("write");
            }
            zout.finish().expect("finish");
        }

        let strict = casual_calc_import::import_package(strict)
            .unwrap_or_else(|e| panic!("{name} in strict form was refused: {e}"));

        // The *modelled* content, not the whole snapshot. ADR-007's retained
        // parts are preserved byte for byte, and this test rewrote namespaces
        // inside them — so a snapshot comparison fails on a difference the test
        // itself introduced. That is what the first version did, and the
        // "failure" was mine rather than the importer's.
        let seen = |import: &casual_calc_import::Import| -> Vec<String> {
            import
                .workbook
                .sheets
                .iter()
                .map(|sheet| {
                    let mut cells: Vec<String> = sheet
                        .cells
                        .iter()
                        .map(|(at, cell)| format!("{}:{}={:?}", at.row, at.col, cell.value))
                        .collect();
                    cells.sort();
                    format!("{}|{}", sheet.name, cells.join(","))
                })
                .collect()
        };
        assert_eq!(
            seen(&strict),
            seen(&transitional),
            "{name} read differently in strict form"
        );
    }
}

/// Deliberately broken packages, from `fixtures/tools/malformed.py`.
///
/// Each violates exactly one thing, so a failure names the violation. What is
/// asserted is the contract, not the verdict: **every file terminates with an
/// answer** — opened, or refused with a reason. Never a panic, never a hang.
///
/// Which of the two is deliberately not asserted per file, because it is a
/// judgement that should be free to change. Excel itself repairs some of these
/// and refuses others, and a test pinning today's choice would make improving
/// the tolerance look like a regression. What must never change is that a file
/// arriving from anywhere cannot take the process down.
#[test]
fn deliberately_broken_packages_are_answered_rather_than_survived() {
    let dir = corpus().join("malformed");
    let Ok(entries) = std::fs::read_dir(&dir) else {
        panic!(
            "run fixtures/tools/malformed.py; {} is missing",
            dir.display()
        );
    };
    let mut files: Vec<_> = entries
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "xlsx"))
        .collect();
    files.sort();
    assert!(
        files.len() >= 6,
        "expected the malformed set, found {files:?}"
    );

    let mut refused = 0;
    for path in &files {
        let bytes = std::fs::read(path).expect("readable");
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        match casual_calc_import::import_package(bytes) {
            // Opened: whatever it kept must be coherent. A sheet list with a
            // sheet in it, and no claim to cells it did not read.
            Ok(import) => {
                assert!(
                    !import.workbook.sheets.is_empty(),
                    "{name} opened with no sheets"
                );
            }
            Err(_) => refused += 1,
        }
    }
    // The security-relevant ones must be refused rather than tolerated: a part
    // name climbing out of the package, a part that is not there, a part that
    // stops mid-tag. Tolerance is a choice everywhere else and not here.
    assert!(
        refused >= 3,
        "only {refused} of {} were refused; path traversal and truncation are not \
         things to be lenient about",
        files.len()
    );
}

/// A file written by LibreOffice, recalculated here, compared against the values
/// LibreOffice itself computed.
///
/// This is the independent oracle the corpus exists for. Every other fidelity
/// assertion in the repository compares this engine against this engine: our
/// importer against our exporter, our evaluator against our own expectations.
/// Here a different implementation wrote the formulas *and* the answers, and if
/// we disagree with it about `=B2*C2` then one of us is wrong and it is worth
/// knowing which.
///
/// The cached values are the point. An `.xlsx` stores what the writing
/// application calculated alongside the formula, so the file carries both the
/// question and that application's answer.
#[test]
fn our_evaluator_agrees_with_libreoffice_about_libreoffices_own_formulas() {
    let path = corpus().join("libreoffice-formulas.xlsx");
    let bytes = std::fs::read(&path).expect("the LibreOffice fixture is present");
    let import = casual_calc_import::import_package(bytes).expect("opens");

    // What LibreOffice stored, for every cell that has a formula.
    let cached: Vec<(casual_calc_model::CellRef, f64)> = import.workbook.sheets[0]
        .cells
        .iter()
        .filter(|(_, cell)| cell.formula.is_some())
        .filter_map(|(at, cell)| match cell.value {
            casual_calc_model::CellValue::Number(n) => Some((at, n)),
            _ => None,
        })
        .collect();
    assert!(
        cached.len() >= 4,
        "the fixture should carry formulas with cached values; found {}",
        cached.len()
    );

    // Recalculate from the formulas alone and compare.
    let mut workbook = import.workbook.clone();
    casual_calc_eval::recalculate(&mut workbook);

    for (at, theirs) in cached {
        let ours = match workbook.sheets[0].cells.get(at).map(|c| c.value.clone()) {
            Some(casual_calc_model::CellValue::Number(n)) => n,
            other => panic!("{at:?}: we produced {other:?} where LibreOffice had {theirs}"),
        };
        assert!(
            (ours - theirs).abs() < 1e-9,
            "{at:?}: we say {ours}, LibreOffice said {theirs}"
        );
    }
}

/// The producers that write a formula's cached value **wrong**, or not at all.
///
/// [`our_evaluator_agrees_with_libreoffice_about_libreoffices_own_formulas`]
/// uses a file whose cached values are correct, which is the easy case and the
/// one Excel and LibreOffice both give us. These two are the other case, and
/// between them they cover what the rest of the ecosystem actually emits:
///
/// * **openpyxl** writes `<f>` with no `<v>`. Every file it has ever written
///   looks like this.
/// * **XlsxWriter** writes `<f>` with `<v>0</v>` — present, well-formed, wrong.
///
/// The three files are the same spreadsheet, so LibreOffice's computed values
/// are the oracle for all of them: one implementation's answers, three ways of
/// writing the question down. An importer that trusted the cache would show a
/// column of zeros for one and blanks for the other, and neither would look
/// like a bug from inside this repository — which is the circularity a corpus
/// exists to break.
#[test]
fn producers_that_cache_nothing_or_cache_zero_still_import_to_the_right_values() {
    let load = |name: &str| {
        let bytes = std::fs::read(corpus().join(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
        casual_calc_import::import_package(bytes)
            .unwrap_or_else(|e| panic!("{name} should open: {e:?}"))
            .workbook
    };

    let truth = load("libreoffice-formulas.xlsx");
    let expected: Vec<(casual_calc_model::CellRef, f64)> = truth.sheets[0]
        .cells
        .iter()
        .filter(|(_, cell)| cell.formula.is_some())
        .filter_map(|(at, cell)| match cell.value {
            casual_calc_model::CellValue::Number(n) => Some((at, n)),
            _ => None,
        })
        .collect();
    assert_eq!(expected.len(), 4, "the oracle carries four answers");

    for (name, stored) in [
        // What each file says *before* we recalculate. Asserted so that a
        // library changing its default leaves a failing test rather than a
        // fixture that still opens, still passes, and no longer tests anything.
        (
            "xlsxwriter-formulas.xlsx",
            casual_calc_model::CellValue::Number(0.0),
        ),
        (
            "openpyxl-formulas.xlsx",
            casual_calc_model::CellValue::Empty,
        ),
    ] {
        let workbook = load(name);
        let cells: Vec<_> = workbook.sheets[0]
            .cells
            .iter()
            .filter(|(_, cell)| cell.formula.is_some())
            .collect();
        assert_eq!(cells.len(), 4, "{name}: four formula cells");
        for (at, cell) in &cells {
            assert_eq!(
                cell.value, stored,
                "{name} at {at:?}: this fixture exists because its producer stores {stored:?} \
                 here; it no longer does, so it is testing something else now"
            );
        }

        let mut recalculated = workbook.clone();
        casual_calc_eval::recalculate(&mut recalculated);
        for &(at, theirs) in &expected {
            let ours = match recalculated.sheets[0]
                .cells
                .get(at)
                .map(|c| c.value.clone())
            {
                Some(casual_calc_model::CellValue::Number(n)) => n,
                other => {
                    panic!("{name} at {at:?}: we produced {other:?}, LibreOffice had {theirs}")
                }
            };
            assert!(
                (ours - theirs).abs() < 1e-9,
                "{name} at {at:?}: we say {ours}, LibreOffice said {theirs}"
            );
        }
    }
}

/// **Shared formulas, checked against Excel's own answers.**
///
/// `45540_classic_Header.xlsx` is an Excel-written file in which one formula —
/// `C10/543` at B10, `ref="B10:B31"` — stands for twenty-two cells, twenty-one
/// of which are the empty `<f t="shared" si="0"/>` that carries no formula text
/// at all. Expanding those is guesswork verified by nothing *inside* this
/// repository, which is exactly the circularity FID-12 names.
///
/// Excel cached its own result in every one of them. So the file states both the
/// question and the answer, and an expansion off by a row disagrees immediately
/// rather than looking plausible.
#[test]
fn shared_formulas_expand_the_way_excel_says_they_do() {
    let bytes = std::fs::read(corpus().join("45540_classic_Header.xlsx")).expect("present");
    let import = casual_calc_import::import_package(bytes).expect("opens");

    let cached: Vec<(usize, casual_calc_model::CellRef, f64)> = import
        .workbook
        .sheets
        .iter()
        .enumerate()
        .flat_map(|(s, sheet)| {
            sheet
                .cells
                .iter()
                .filter(|(_, cell)| cell.formula.is_some())
                .filter_map(move |(at, cell)| match cell.value {
                    casual_calc_model::CellValue::Number(n) => Some((s, at, n)),
                    _ => None,
                })
        })
        .collect();
    assert!(
        cached.len() >= 60,
        "this file's whole value is its many cached formula results; found {}",
        cached.len()
    );

    let mut workbook = import.workbook.clone();
    casual_calc_eval::recalculate(&mut workbook);
    for (sheet, at, theirs) in cached {
        let ours = match workbook.sheets[sheet]
            .cells
            .get(at)
            .map(|c| c.value.clone())
        {
            Some(casual_calc_model::CellValue::Number(n)) => n,
            other => panic!("sheet {sheet} {at:?}: we produced {other:?}, Excel had {theirs}"),
        };
        assert!(
            (ours - theirs).abs() <= 1e-9 * theirs.abs().max(1.0),
            "sheet {sheet} {at:?}: we say {ours}, Excel said {theirs}"
        );
    }
}

/// **A real file that names none of its positions.**
///
/// `56278.xlsx` is Excel-written and uses `<c t="inlineStr">` with no `r`, inside
/// `<row>` with no `r`, in a sheet with no `<dimension>`. All three are legal —
/// `r` is optional in ECMA-376 and position is implied by ordinal — and all three
/// are unusual enough that treating them as required survives a long time.
///
/// It did survive: before this, the file imported as **ten sheets and zero
/// cells**. It opened, so the open-rate guard passed; the corpus-wide cell count
/// passed because other files have cells. Nothing was left to notice that an
/// entire real document had been silently dropped.
#[test]
fn cells_without_an_r_attribute_land_where_their_position_says() {
    let bytes = std::fs::read(corpus().join("56278.xlsx")).expect("present");
    let import = casual_calc_import::import_package(bytes).expect("opens");

    let total: usize = import
        .workbook
        .sheets
        .iter()
        .map(|s| s.cells.iter().count())
        .sum();
    assert!(
        total > 500,
        "every cell in this file is positioned by ordinal; found {total}"
    );

    // Not merely present — in the right place. The first sheet reads:
    //
    //     A1  Market Rates
    //     A3  Description     B3  Rate
    //     A4  Prime           B4  0.032500
    //
    // A reader that counted wrong would still produce cells, just shifted, so
    // the addresses are the assertion and the count above is only the alarm.
    let text = |row: u32, col: u32| -> String {
        match import.workbook.sheets[0]
            .cells
            .get(casual_calc_model::CellRef::new(row, col))
            .map(|c| c.value.clone())
        {
            Some(
                casual_calc_model::CellValue::InlineString(id)
                | casual_calc_model::CellValue::SharedString(id),
            ) => import
                .workbook
                .strings
                .get(id)
                .unwrap_or_default()
                .to_owned(),
            other => panic!("({row},{col}) is {other:?}, not text"),
        }
    };
    assert_eq!(text(0, 0), "Market Rates");
    assert_eq!(text(2, 0), "Description");
    assert_eq!(text(2, 1), "Rate");
    assert_eq!(text(3, 0), "Prime");
}

/// **The 1904 epoch, from a producer that actually writes it.**
///
/// Every previous 1904 assertion in this repository was made against a file this
/// repository wrote, which proves the reader agrees with the writer and nothing
/// else. XlsxWriter writes `date1904="1"` and stores the serial its own way.
///
/// 2020-02-29 is serial 42428 under the 1904 system and 43890 under 1900. A
/// reader that ignores the flag is out by 1462 days — four years and a day,
/// which renders as a perfectly plausible date in 2016.
#[test]
fn the_1904_epoch_is_read_from_the_file_rather_than_assumed() {
    let bytes = std::fs::read(corpus().join("xlsxwriter-1904.xlsx")).expect("present");
    let import = casual_calc_import::import_package(bytes).expect("opens");
    assert!(import.workbook.date1904, "the file says so");

    let cell = import.workbook.sheets[0]
        .cells
        .get(casual_calc_model::CellRef::new(0, 1))
        .expect("B1 holds the date");
    assert_eq!(
        cell.value,
        casual_calc_model::CellValue::Number(42428.0),
        "the serial is the file's, unconverted"
    );

    // The serial alone proves nothing; what matters is the date a person sees.
    assert_eq!(
        casual_calc_layout::display_text(&import.workbook, cell),
        "2020-02-29",
        "under the 1900 epoch this same serial reads 2016-02-28"
    );
}

/// **An array formula from a producer that writes `t="array"`.**
///
/// `{=SUM(A1:A3*B1:B3)}` in one cell: the element-wise product of two ranges,
/// summed, which is only correct if the multiplication is evaluated as arrays
/// rather than coerced to scalars. 1x10 + 2x20 + 3x30 = 140.
///
/// XlsxWriter caches zero for it, as it does for every formula, so the answer
/// here has to be computed rather than believed.
#[test]
fn an_array_formula_written_by_another_tool_evaluates_element_wise() {
    let bytes = std::fs::read(corpus().join("xlsxwriter-array.xlsx")).expect("present");
    let import = casual_calc_import::import_package(bytes).expect("opens");
    let at = casual_calc_model::CellRef::new(0, 3);
    assert!(
        import.workbook.sheets[0]
            .cells
            .get(at)
            .is_some_and(|c| c.formula.is_some()),
        "D1 carries the array formula"
    );

    let mut workbook = import.workbook.clone();
    casual_calc_eval::recalculate(&mut workbook);
    assert_eq!(
        workbook.sheets[0].cells.get(at).map(|c| c.value.clone()),
        Some(casual_calc_model::CellValue::Number(140.0)),
        "scalar coercion would give 10 here, not 140"
    );
}
